template<int... Ns> struct CompileSum;

// Base case: Empty pack
template<>
struct CompileSum<> {
    static constexpr int value = 0;
};

// Recursive step: Head and Tail pack expansion
template<int Head, int... Tail>
struct CompileSum<Head, Tail...> {
    static constexpr int value = Head + CompileSum<Tail...>::value;
};

// Usage Example (C++17/20 deduction guide not needed for struct lookup)
constexpr int V1 = CompileSum<10, 5, 20>::value; // 35
constexpr int V2 = CompileSum<>::value;          // 0
constexpr int V3 = CompileSum<42>::value;        // 42
